package com.example.prawnhub_v2;

import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.Button;
import android.widget.TextView;
import androidx.annotation.NonNull;
import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.components.Description;
import com.github.mikephil.charting.data.Entry;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;
import com.google.android.material.progressindicator.CircularProgressIndicator;
import com.google.firebase.database.DataSnapshot;
import com.google.firebase.database.DatabaseError;
import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.database.ValueEventListener;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Configured-duration culture tracking; sensor readings are never presented as measured growth. */
public class GrowthActivity extends BaseNavActivity {
    private static final String TAG = "PRAWNHUB_GROWTH";
    private final SimpleDateFormat storedDate = new SimpleDateFormat("yyyy-MM-dd", Locale.US);
    private final SimpleDateFormat displayDate = new SimpleDateFormat("dd MMMM yyyy", Locale.US);
    private DatabaseReference root;
    private DatabaseReference settingsRef, growthRef, sensorsRef, historyRef;
    private ValueEventListener settingsListener, growthListener, sensorsListener, historyListener;
    private TextView startDateText, cultureDaysText, remainingDaysText, harvestText, scoreText, mlPredictionText, stageText, statusText, analysisText, tempText, tdsText, turbText, waterText, trendEmpty;
    private CircularProgressIndicator progress;
    private LineChart chart;
    private Button setStartDateButton, harvestButton, resetCultureButton;
    private String startDate="", cultureStatus="active", harvestedAt="", readinessNotificationId="";
    private long startMillis;
    private int cultureDays;
    private float minTemp=28, maxTemp=32, minTds=15, maxTds=25, minTurb=0, maxTurb=45, overflowLimit=5;
    private Float liveTemp, liveTds, liveTurb, liveWater;
    private boolean sensorsActive;
    private long sensorsLastUpdate;
    private boolean resetInProgress;
    private List<Sample> samples=Collections.emptyList();
    private List<Integer> completedCultureDurations=Collections.emptyList();
    private final GrowthPredictionService predictionService = new UnavailableGrowthPredictionService();

    @Override protected void onCreate(Bundle state) {
        super.onCreate(state); setContentView(R.layout.activity_growth); setupBottomNav(); root=FirebaseDatabase.getInstance().getReference(); settingsRef=root.child("settings"); growthRef=root.child("growth"); sensorsRef=root.child("ShrimpHub"); historyRef=root.child("ShrimpHub/history"); bind();
        findViewById(R.id.backButton).setOnClickListener(v->finish()); setStartDateButton.setOnClickListener(v->selectStartDate()); harvestButton.setOnClickListener(v->confirmHarvest()); resetCultureButton.setOnClickListener(v->confirmReset());
        listenSettings(); listenGrowth(); listenSensors(); listenHistory();
    }
    private void bind() {
        startDateText=t(R.id.cultureStartDateText); cultureDaysText=t(R.id.cultureDaysInfoText); remainingDaysText=t(R.id.remainingDaysText); harvestText=t(R.id.targetText); scoreText=t(R.id.scoreText); mlPredictionText=t(R.id.mlPredictionText); stageText=t(R.id.growthStageText); statusText=t(R.id.statusBadge); analysisText=t(R.id.recommendationsText); tempText=t(R.id.temperatureConditionText); tdsText=t(R.id.tdsConditionText); turbText=t(R.id.turbidityConditionText); waterText=t(R.id.waterLevelConditionText); trendEmpty=t(R.id.growthTrendEmptyText);
        progress=findViewById(R.id.healthProgress); chart=findViewById(R.id.growthChart); setStartDateButton=findViewById(R.id.setStartDateButton); harvestButton=findViewById(R.id.harvestButton); resetCultureButton=findViewById(R.id.resetCultureButton);
        Description d=new Description(); d.setText("Pond conditions based on calibrated sensor readings (0-100)"); chart.setDescription(d);
    }
    private TextView t(int id){return findViewById(id);}
    private void listenSettings(){settingsListener=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){minTemp=num(s,"min_temp",28);maxTemp=num(s,"max_temp",32);minTds=num(s,"min_sal",15);maxTds=num(s,"max_sal",25);minTurb=num(s,"min_turb",0);maxTurb=num(s,"max_turb",45);overflowLimit=num(s,"overflow_limit",5);render();}@Override public void onCancelled(@NonNull DatabaseError e){Log.w(TAG,"Settings read failed",e.toException());render();}};settingsRef.addValueEventListener(settingsListener);}
    private void listenGrowth(){growthListener=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){startDate=str(s,"start_date");cultureStatus=str(s,"status");if(cultureStatus.isEmpty())cultureStatus="active";harvestedAt=str(s,"harvested_at");readinessNotificationId=str(s,"last_harvest_readiness_notification_id");completedCultureDurations=readCompletedCultureDurations(s.child("completed_cultures"));startMillis=parseStoredDate(startDate);cultureDays=startMillis==0?0:(int)Math.max(0,TimeUnit.MILLISECONDS.toDays(System.currentTimeMillis()-startMillis));render();}@Override public void onCancelled(@NonNull DatabaseError e){Log.w(TAG,"Growth read failed",e.toException());startDate="";startMillis=0;completedCultureDurations=Collections.emptyList();render();}};growthRef.addValueEventListener(growthListener);}
    private void listenSensors(){sensorsListener=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){liveTemp=value(s,"temperature");liveTds=value(s,"tds");liveTurb=value(s,"turbidity");liveWater=value(s,"waterLevel");sensorsActive=Boolean.TRUE.equals(s.child("sensors_active").getValue(Boolean.class));sensorsLastUpdate=parseTimestamp(s.child("sensors_last_update").getValue());if(sensorsActive&&sensorsLastUpdate>0&&System.currentTimeMillis()-sensorsLastUpdate>120000L)sensorsActive=false;if(!sensorsActive&&sensorsLastUpdate==0&&nonZero(liveTemp,liveTds,liveTurb,liveWater))sensorsActive=true;render();}@Override public void onCancelled(@NonNull DatabaseError e){Log.w(TAG,"Sensor read failed",e.toException());sensorsActive=false;render();}};sensorsRef.addValueEventListener(sensorsListener);}
    private void listenHistory(){historyListener=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot rootSnapshot){Map<Long,SampleBuilder> grouped=new HashMap<>();for(DataSnapshot row:rootSnapshot.getChildren())addHistory(grouped,row);List<Sample> valid=new ArrayList<>();for(Map.Entry<Long,SampleBuilder> e:grouped.entrySet())if(e.getValue().complete())valid.add(e.getValue().build(e.getKey()));valid.sort(Comparator.comparingLong(v->v.time));samples=valid;Log.d(TAG,"Valid growth-history samples: "+samples.size());render();}@Override public void onCancelled(@NonNull DatabaseError e){Log.w(TAG,"History read failed",e.toException());samples=Collections.emptyList();render();}};historyRef.addValueEventListener(historyListener);}
    private void addHistory(Map<Long,SampleBuilder> grouped,DataSnapshot row){long time=parseTimestamp(row.child("timestamp").getValue());if(time==0)return;SampleBuilder b=grouped.containsKey(time)?grouped.get(time):new SampleBuilder();Float temp=value(row,"temperature"),tds=value(row,"tds"),turb=value(row,"turbidity"),water=value(row,"waterLevel");if(temp!=null)b.temp=temp;if(tds!=null)b.tds=tds;if(turb!=null)b.turb=turb;if(water!=null)b.water=water;Float recorded=value(row,"rec_val");String type=str(row,"param_type");if(recorded!=null){if("temp".equals(type)||"temperature".equals(type))b.temp=recorded;if("salinity".equals(type)||"tds".equals(type))b.tds=recorded;if("turbidity".equals(type))b.turb=recorded;if("water_level".equals(type))b.water=recorded;}grouped.put(time,b);}
    private List<Integer> readCompletedCultureDurations(DataSnapshot cultures){List<Integer> durations=new ArrayList<>();for(DataSnapshot culture:cultures.getChildren()){long started=parseStoredDate(str(culture,"start_date"));long harvested=parseTimestamp(culture.child("harvested_at").getValue());if(started>0&&harvested>started){durations.add((int)TimeUnit.MILLISECONDS.toDays(harvested-started));}}return durations;}
    private void render(){renderSensors();boolean started=startMillis>0,harvested="harvested".equalsIgnoreCase(cultureStatus);if(!started){renderNotStarted();return;}startDateText.setText("Culture Start Date: "+displayDate.format(new Date(startMillis)));cultureDaysText.setText("Culture Days: "+cultureDays);if(harvested){renderHarvested();return;}HarvestPredictionEstimator.Estimate estimate=HarvestPredictionEstimator.fromCompletedCultures(completedCultureDurations);if(!estimate.available){renderUnavailablePrediction(estimate.message);return;}Calendar harvest=Calendar.getInstance();harvest.setTimeInMillis(startMillis);harvest.add(Calendar.DAY_OF_YEAR,estimate.durationDays);int remaining=Math.max(0,estimate.durationDays-cultureDays);int percent=Math.min(100,Math.max(0,Math.round(cultureDays*100f/estimate.durationDays)));progress.setProgress(percent);scoreText.setText("Growth Progress: "+percent+"%");remainingDaysText.setText("Estimated Remaining Days: "+remaining);harvestText.setText("Predicted Harvest Date: "+displayDate.format(harvest.getTime()));stageText.setText("Growth Stage: Historical harvest estimate");statusText.setText(cultureDays>=estimate.durationDays?"Condition: Ready for harvest review":"Condition: Culture in progress");analysisText.setText("Historical harvest estimate based on "+estimate.sampleCount+" completed cultures; this is not a machine-learning prediction or biological guarantee.");renderMlPrediction();harvestButton.setEnabled(cultureDays>=estimate.durationDays);resetCultureButton.setEnabled(!resetInProgress);setStartDateButton.setText("Set Start Date");showTrend();if(cultureDays>=estimate.durationDays)notifyOnce(startDate+":"+estimate.durationDays);}
    private void renderSensors(){PondConditionEvaluator.Result conditions=PondConditionEvaluator.evaluate(liveTemp,liveTds,liveTurb,liveWater,minTemp,maxTemp,minTds,maxTds,minTurb,maxTurb,overflowLimit);tempText.setText(live("Temperature",liveTemp,"C",conditions.temperature));tdsText.setText(live("TDS",liveTds,"ppm",conditions.tds));turbText.setText(live("Turbidity",liveTurb,"NTU",conditions.turbidity));waterText.setText(live("Water Level",liveWater,"cm",conditions.water));}
    private String live(String name,Float v,String unit,PondConditionEvaluator.Status status){if(v==null)return name+": Unavailable";if(!sensorsActive)return String.format(Locale.US,"%s: %.1f %s - Unavailable (stale or disconnected)",name,v,unit);return String.format(Locale.US,"%s: %.1f %s - %s",name,v,unit,status==PondConditionEvaluator.Status.NORMAL?"Normal":status==PondConditionEvaluator.Status.CRITICAL?"Critical":"Warning");}
    private void renderMlPrediction(){List<GrowthPredictionService.HistorySample> input=new ArrayList<>();for(Sample sample:samples)input.add(new GrowthPredictionService.HistorySample(sample.time,sample.temp,sample.tds,sample.turb,sample.water));GrowthPredictionService.PredictionResult result=predictionService.predict(new GrowthPredictionService.PredictionInput(cultureDays,0,input));mlPredictionText.setText(result.message);Log.i(TAG,"Growth prediction status: "+result.message);}
    private void renderNotStarted(){progress.setProgress(0);startDateText.setText("Culture Start Date: Not Set");cultureDaysText.setText("Culture Days: --");remainingDaysText.setText("Remaining Days: Unavailable");scoreText.setText("Growth Progress: Unavailable");mlPredictionText.setText("ML prediction unavailable: no trained model is configured.");harvestText.setText("Target Harvest Date: Unavailable");stageText.setText("Growth Stage: Not Started");statusText.setText("Harvest Readiness: Not Available");analysisText.setText("Set a new culture start date to begin duration tracking.");harvestButton.setEnabled(false);setStartDateButton.setText("Set Start Date");resetCultureButton.setEnabled(!resetInProgress);showEmpty("Growth trend will appear after the culture start date is set and valid sensor history is recorded.");}
    private void renderUnavailablePrediction(String message){progress.setProgress(0);remainingDaysText.setText("Estimated Remaining Days: Unavailable");scoreText.setText("Growth Progress: Unavailable");mlPredictionText.setText("ML prediction unavailable: no trained model is configured.");harvestText.setText("Predicted Harvest Date: Unavailable");stageText.setText("Growth Stage: Historical data required");statusText.setText("Condition: Harvest estimate unavailable");analysisText.setText(message);harvestButton.setEnabled(false);resetCultureButton.setEnabled(!resetInProgress);showTrend();}
    private void renderHarvested(){progress.setProgress(100);remainingDaysText.setText("Remaining Days: 0");scoreText.setText("Growth Progress: 100%");mlPredictionText.setText("ML prediction unavailable: no trained model is configured.");harvestText.setText("Harvest Date: "+readableHarvestDate());stageText.setText("Growth Stage: Harvested");statusText.setText("Condition: Culture Harvested");analysisText.setText("This culture is complete. Start a new culture when a new stocking cycle begins.");harvestButton.setEnabled(false);setStartDateButton.setText("Start New Culture");resetCultureButton.setEnabled(false);showEmpty("This culture has been harvested. Its recorded sensor history remains available for reports.");}
    private void showTrend(){List<Sample> after=new ArrayList<>();for(Sample s:samples)if(s.time>=startMillis)after.add(s);if(after.size()<2){showEmpty("More valid sensor data is required after the culture start date to display the Growth Trend.");return;}chart.setVisibility(View.VISIBLE);trendEmpty.setVisibility(View.GONE);List<Entry> points=new ArrayList<>();for(Sample s:after){PondConditionEvaluator.Result conditions=PondConditionEvaluator.evaluate(s.temp,s.tds,s.turb,s.water,minTemp,maxTemp,minTds,maxTds,minTurb,maxTurb,overflowLimit);if(conditions.settingsValid&&conditions.availableCount==4)points.add(new Entry(s.time/1000f,conditions.score));}if(points.size()<2){showEmpty("Growth Trend needs complete calibrated sensor history.");return;}LineDataSet set=new LineDataSet(points,"Growth conditions (0-100)");set.setColor(android.graphics.Color.rgb(63,140,133));set.setCircleColor(android.graphics.Color.rgb(242,140,111));set.setLineWidth(2f);chart.setData(new LineData(set));chart.invalidate();}
    private void showEmpty(String message){chart.clear();chart.setVisibility(View.GONE);trendEmpty.setText(message);trendEmpty.setVisibility(View.VISIBLE);}
    private void notifyOnce(String eventId){if(eventId.equals(readinessNotificationId))return;root.child("growth/last_harvest_readiness_notification_id").setValue(eventId).addOnSuccessListener(v->NotificationHelper.showAlert(this,"Harvesting time!","Your prawns may be ready for harvest. Please review the pond conditions before proceeding.",3001));}
    private void confirmHarvest(){if(!harvestButton.isEnabled())return;new AlertDialog.Builder(this).setTitle("Mark culture as harvested?").setMessage("This records the current culture as harvested. It does not control pumps, relays, or the feeder.").setNegativeButton("Cancel",null).setPositiveButton("Harvest",(d,w)->saveHarvest()).show();}
    private void saveHarvest(){harvestButton.setEnabled(false);long now=System.currentTimeMillis();String id=startDate+"_"+now;Map<String,Object> updates=new HashMap<>();updates.put("growth/status","harvested");updates.put("growth/harvested_at",now);updates.put("growth/completed_cultures/"+id+"/start_date",startDate);updates.put("growth/completed_cultures/"+id+"/harvested_at",now);root.updateChildren(updates).addOnSuccessListener(v->android.widget.Toast.makeText(this,"Culture marked as harvested.",android.widget.Toast.LENGTH_SHORT).show()).addOnFailureListener(e->{android.widget.Toast.makeText(this,"Harvest could not be saved. Please retry.",android.widget.Toast.LENGTH_LONG).show();render();});}
    private void confirmReset(){if(resetInProgress)return;if("harvested".equalsIgnoreCase(cultureStatus)){android.widget.Toast.makeText(this,"This culture is already harvested. Use Start New Culture instead.",android.widget.Toast.LENGTH_LONG).show();return;}if(startMillis==0){android.widget.Toast.makeText(this,"No active culture to reset.",android.widget.Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Reset Culture?").setMessage("Are you sure you want to reset the current culture? The active growth data and harvest prediction will be cleared, and you will need to set a new culture start date.").setNegativeButton("Cancel",null).setPositiveButton("Reset Culture",(dialog,which)->resetCulture()).show();}
    private void resetCulture(){resetInProgress=true;resetCultureButton.setEnabled(false);long now=System.currentTimeMillis();String id=startDate+"_reset_"+now;Map<String,Object> updates=new HashMap<>();updates.put("growth/reset_cultures/"+id+"/start_date",startDate);updates.put("growth/reset_cultures/"+id+"/reset_at",now);updates.put("growth/start_date","");updates.put("growth/status","inactive");updates.put("growth/harvested_at",null);updates.put("growth/last_harvest_readiness_notification_id",null);root.updateChildren(updates).addOnSuccessListener(v->{resetInProgress=false;android.widget.Toast.makeText(this,"Culture reset. Set a new start date to continue.",android.widget.Toast.LENGTH_SHORT).show();}).addOnFailureListener(e->{resetInProgress=false;resetCultureButton.setEnabled(true);android.widget.Toast.makeText(this,"Culture reset failed. Please retry.",android.widget.Toast.LENGTH_LONG).show();});}
    private void selectStartDate(){Calendar now=Calendar.getInstance();new DatePickerDialog(this,(v,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.clear();chosen.set(y,m,d);if(chosen.after(today())){new AlertDialog.Builder(this).setMessage("The culture start date cannot be in the future.").setPositiveButton("OK",null).show();return;}String candidate=storedDate.format(chosen.getTime());String action="harvested".equalsIgnoreCase(cultureStatus)?"Start a new culture":"Save culture start date";new AlertDialog.Builder(this).setTitle(action).setMessage(action+" as "+displayDate.format(chosen.getTime())+"?").setNegativeButton("Cancel",null).setPositiveButton("Save",(dialog,which)->startCulture(candidate)).show();},now.get(Calendar.YEAR),now.get(Calendar.MONTH),now.get(Calendar.DAY_OF_MONTH)).show();}
    private void startCulture(String date){Map<String,Object> updates=new HashMap<>();updates.put("growth/start_date",date);updates.put("growth/status","active");updates.put("growth/harvested_at",null);updates.put("growth/last_harvest_readiness_notification_id",null);root.updateChildren(updates).addOnFailureListener(e->android.widget.Toast.makeText(this,"Culture start date could not be saved.",android.widget.Toast.LENGTH_LONG).show());}
    @Override protected void onDestroy(){if(settingsListener!=null)settingsRef.removeEventListener(settingsListener);if(growthListener!=null)growthRef.removeEventListener(growthListener);if(sensorsListener!=null)sensorsRef.removeEventListener(sensorsListener);if(historyListener!=null)historyRef.removeEventListener(historyListener);super.onDestroy();}
    private String readableHarvestDate(){long time=parseTimestamp(harvestedAt);return time==0?"Recorded":displayDate.format(new Date(time));}
    private Calendar today(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}
    private float num(DataSnapshot s,String key,float fallback){Float v=value(s,key);return v==null?fallback:v;}
    private Float value(DataSnapshot s,String key){Object v=s.child(key).getValue();if(v instanceof Number)return ((Number)v).floatValue();try{return v==null?null:Float.parseFloat(String.valueOf(v));}catch(NumberFormatException e){return null;}}
    private String str(DataSnapshot s,String key){Object v=s.child(key).getValue();return v==null?"":String.valueOf(v);}
    private boolean nonZero(Float... values){for(Float v:values)if(v!=null&&v!=0f)return true;return false;}
    private long parseStoredDate(String value){try{Date d=storedDate.parse(value);return d==null?0:d.getTime();}catch(Exception e){return 0;}}
    private long parseTimestamp(Object value){if(value instanceof Number){long raw=((Number)value).longValue();return raw<100000000000L?raw*1000:raw;}if(value==null)return 0;try{return parseTimestamp(Long.parseLong(String.valueOf(value)));}catch(NumberFormatException e){return 0;}}
    private static final class Sample{final long time;final float temp,tds,turb,water;Sample(long time,float temp,float tds,float turb,float water){this.time=time;this.temp=temp;this.tds=tds;this.turb=turb;this.water=water;}}
    private static final class SampleBuilder{Float temp,tds,turb,water;boolean complete(){return temp!=null&&tds!=null&&turb!=null&&water!=null;}Sample build(long time){return new Sample(time,temp,tds,turb,water);}}
}
